#[derive(Debug, Clone, Copy, Hash, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum UsageBasis {
    Native,
    LocalDerived,
}

impl UsageBasis {
    fn as_str(self) -> &'static str {
        match self {
            UsageBasis::Native => USAGE_BASIS_NATIVE,
            UsageBasis::LocalDerived => USAGE_BASIS_LOCAL_DERIVED,
        }
    }

    fn from_raw(raw: &str) -> Self {
        if raw.eq_ignore_ascii_case(USAGE_BASIS_LOCAL_DERIVED) {
            UsageBasis::LocalDerived
        } else {
            UsageBasis::Native
        }
    }
}

impl std::fmt::Display for UsageBasis {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

