fn ensure_usage_schema(conn: &Connection) -> Result<()> {
    add_column_if_missing(
        conn,
        "usage_daily_model_rollups",
        "message_count",
        "INTEGER NOT NULL DEFAULT 0",
    )?;
    add_column_if_missing(
        conn,
        "usage_daily_model_rollups",
        "source_cost",
        "REAL NOT NULL DEFAULT 0",
    )?;
    add_column_if_missing(
        conn,
        "usage_sessions",
        "usage_basis",
        "TEXT NOT NULL DEFAULT 'native'",
    )?;
    add_column_if_missing(
        conn,
        "usage_daily_model_rollups",
        "usage_basis",
        "TEXT NOT NULL DEFAULT 'native'",
    )?;
    rebuild_usage_daily_model_rollups_for_usage_basis(conn)?;
    ensure_usage_scan_file_cache_schema(conn)?;
    ensure_usage_rollup_sources_schema(conn)?;
    conn.execute_batch(
        r#"
        CREATE UNIQUE INDEX IF NOT EXISTS idx_usage_rollups_basis_unique
          ON usage_daily_model_rollups(device_id, day, agent, model, account, usage_basis);
        CREATE INDEX IF NOT EXISTS idx_usage_rollups_basis_dirty
          ON usage_daily_model_rollups(dirty, usage_basis);
        "#,
    )?;
    Ok(())
}

