    fn make_message(seed: i64) -> LocalUsageMessage {
        LocalUsageMessage {
            agent: "codex".to_string(),
            model: "gpt-5-20260101".to_string(),
            provider: "openai".to_string(),
            session_id: format!("session-{seed}"),
            account: "local".to_string(),
            timestamp_ms: 1_789_000_000_000 + seed,
            day: "2026-06-16".to_string(),
            tokens: TokenBuckets {
                input: 10,
                output: 20,
                cache_read: 3,
                cache_write: 4,
                reasoning: 5,
            },
            source_cost: 0.01,
            message_count: 1,
            usage_basis: UsageBasis::Native,
            dedup_key: format!("dedup-{seed}"),
        }
    }

    fn test_scan_window() -> ScanWindow {
        ScanWindow {
            since_day: None,
            until_day: None,
            start_ms: 0,
            end_ms: i64::MAX,
        }
    }

    #[test]
    fn explicit_scan_window_is_clamped_to_thirty_days() {
        let open_ended = ScanWindow::from_options(&UsageScanOptions {
            tools: vec!["codex".to_string()],
            since: Some("2000-01-01".to_string()),
            until: None,
        });
        assert_eq!(open_ended.since_day.as_deref(), Some("2000-01-01"));
        assert_eq!(open_ended.until_day.as_deref(), Some("2000-01-30"));

        let long_backfill = ScanWindow::from_options(&UsageScanOptions {
            tools: vec!["codex".to_string()],
            since: Some("2000-01-01".to_string()),
            until: Some("2000-03-15".to_string()),
        });
        assert_eq!(long_backfill.since_day.as_deref(), Some("2000-01-01"));
        assert_eq!(long_backfill.until_day.as_deref(), Some("2000-01-30"));

        let small_backfill = ScanWindow::from_options(&UsageScanOptions {
            tools: vec!["codex".to_string()],
            since: Some("2000-01-01".to_string()),
            until: Some("2000-01-10".to_string()),
        });
        assert_eq!(small_backfill.since_day.as_deref(), Some("2000-01-01"));
        assert_eq!(small_backfill.until_day.as_deref(), Some("2000-01-10"));
    }

    #[test]
    fn usage_auxiliary_pruning_keeps_newest_rows() {
        with_home(|_| {
            let conn = open_usage_db().unwrap();
            for idx in 0..5 {
                conn.execute(
                    "INSERT INTO usage_scan_file_cache
                     (tool, path, size_bytes, mtime_ms, window_start_ms, window_end_ms, scanned_at_ms)
                     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
                    params![
                        "codex",
                        format!("/tmp/source-{idx}.jsonl"),
                        idx,
                        idx,
                        0,
                        100,
                        idx
                    ],
                )
                .unwrap();
                conn.execute(
                    "INSERT INTO usage_monitoring_seen (source_key, event_type) VALUES (?1, ?2)",
                    params![format!("source-key-{idx}"), "prompt"],
                )
                .unwrap();
            }

            assert_eq!(
                prune_table_by_rowid(&conn, "usage_scan_file_cache", 3).unwrap(),
                2
            );
            assert_eq!(
                prune_table_by_rowid(&conn, "usage_monitoring_seen", 3).unwrap(),
                2
            );

            for table in ["usage_scan_file_cache", "usage_monitoring_seen"] {
                let (min_rowid, count): (i64, i64) = conn
                    .query_row(
                        &format!(
                            "SELECT MIN(rowid), COUNT(*) FROM {}",
                            quote_identifier(table)
                        ),
                        [],
                        |row| Ok((row.get(0)?, row.get(1)?)),
                    )
                    .unwrap();
                assert_eq!(count, 3, "{table} should be capped");
                assert_eq!(min_rowid, 3, "{table} should prune oldest rows first");
            }
        });
    }

    #[test]
    fn rollup_source_pruning_subtracts_old_contributions_before_rescan() {
        with_home(|home| {
            let mut conn = open_usage_db().unwrap();
            for idx in 0..5 {
                let file = test_source_file(home, &format!("sources/codex/source-{idx}.jsonl"));
                let mut msg = make_message(idx);
                msg.tokens.input = idx + 1;
                msg.tokens.output = 0;
                msg.tokens.cache_read = 0;
                msg.tokens.cache_write = 0;
                msg.tokens.reasoning = 0;
                msg.source_cost = 0.0;
                replace_rollup_source(&mut conn, "codex", &file, &[msg]).unwrap();
                mark_source_file_scanned(&conn, "codex", &file, &test_scan_window()).unwrap();
            }

            assert_eq!(source_rollup_count(&conn, "codex"), 5);
            assert_eq!(scan_file_cache_count(&conn, "codex"), 5);
            assert_eq!(agent_rollup_totals(&conn, "codex"), (15, 0, 5));
            assert_eq!(prune_rollup_source_rows(&mut conn, 3).unwrap(), 2);
            assert_eq!(source_rollup_count(&conn, "codex"), 3);
            assert_eq!(scan_file_cache_count(&conn, "codex"), 3);
            assert_eq!(agent_rollup_totals(&conn, "codex"), (12, 0, 3));

            let file = test_source_file(home, "sources/codex/source-0.jsonl");
            let mut changed = make_message(100);
            changed.tokens.input = 100;
            changed.tokens.output = 0;
            changed.tokens.cache_read = 0;
            changed.tokens.cache_write = 0;
            changed.tokens.reasoning = 0;
            changed.source_cost = 0.0;
            replace_rollup_source(&mut conn, "codex", &file, &[changed]).unwrap();

            assert_eq!(source_rollup_count(&conn, "codex"), 4);
            assert_eq!(agent_rollup_totals(&conn, "codex"), (112, 0, 4));
        });
    }

    #[test]
    fn rollup_retention_prunes_old_aggregates_sources_and_scan_cache() {
        with_home(|home| {
            let mut conn = open_usage_db().unwrap();
            let old_file = test_source_file(home, "sources/codex/old-retention.jsonl");
            let recent_file = test_source_file(home, "sources/codex/recent-retention.jsonl");
            let mut old_msg = make_message(1);
            old_msg.day = "2000-01-01".to_string();
            let mut recent_msg = make_message(2);
            recent_msg.day = Utc::now().date_naive().format("%Y-%m-%d").to_string();

            replace_rollup_source(&mut conn, "codex", &old_file, &[old_msg]).unwrap();
            replace_rollup_source(&mut conn, "codex", &recent_file, &[recent_msg]).unwrap();
            mark_source_file_scanned(&conn, "codex", &old_file, &test_scan_window()).unwrap();
            mark_source_file_scanned(&conn, "codex", &recent_file, &test_scan_window()).unwrap();

            assert_eq!(prune_usage_rollups_by_retention(&mut conn, 180).unwrap(), 2);

            let old_rollups: i64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM usage_daily_model_rollups WHERE day = '2000-01-01'",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(old_rollups, 0);
            assert_eq!(source_rollup_count(&conn, "codex"), 1);
            assert_eq!(scan_file_cache_count(&conn, "codex"), 1);
        });
    }

    #[test]
    fn daily_rollup_row_cap_prunes_matching_sources_and_scan_cache() {
        with_home(|home| {
            let mut conn = open_usage_db().unwrap();
            for idx in 0..5 {
                let file = test_source_file(home, &format!("sources/codex/cap-{idx}.jsonl"));
                let mut msg = make_message(idx);
                msg.day = format!("2026-06-1{idx}");
                msg.tokens.input = idx + 1;
                msg.tokens.output = 0;
                msg.tokens.cache_read = 0;
                msg.tokens.cache_write = 0;
                msg.tokens.reasoning = 0;
                msg.source_cost = 0.0;
                replace_rollup_source(&mut conn, "codex", &file, &[msg]).unwrap();
                mark_source_file_scanned(&conn, "codex", &file, &test_scan_window()).unwrap();
            }

            assert_eq!(prune_usage_daily_rollup_rows(&mut conn, 3).unwrap(), 4);
            assert_eq!(source_rollup_count(&conn, "codex"), 3);
            assert_eq!(scan_file_cache_count(&conn, "codex"), 3);

            let min_day: String = conn
                .query_row(
                    "SELECT MIN(day) FROM usage_daily_model_rollups WHERE agent = 'codex'",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(min_day, "2026-06-12");
        });
    }

    fn monitoring_rows() -> Vec<(String, Option<String>, String, i64, i64, Option<String>)> {
        let records = open_records_db().unwrap();
        let mut stmt = records
            .prepare(
                "SELECT metadata, prompt_summary, file_path, added_lines, removed_lines, diff_hunk
                 FROM records ORDER BY id",
            )
            .unwrap();
        stmt.query_map([], |row| {
            Ok((
                row.get::<_, Option<String>>(0)?.unwrap_or_default(),
                row.get(1)?,
                row.get(2)?,
                row.get(3)?,
                row.get(4)?,
                row.get(5)?,
            ))
        })
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap()
    }

    fn monitoring_event_types_for_agent(agent: &str) -> HashSet<String> {
        let records = open_records_db().unwrap();
        let mut stmt = records
            .prepare("SELECT metadata FROM records WHERE tool = ?1 ORDER BY id")
            .unwrap();
        stmt.query_map(params![agent], |row| row.get::<_, Option<String>>(0))
            .unwrap()
            .filter_map(|row| row.ok().flatten())
            .filter_map(|metadata| {
                serde_json::from_str::<Value>(&metadata)
                    .ok()?
                    .get("event_type")
                    .and_then(Value::as_str)
                    .map(str::to_string)
            })
            .collect()
    }

