    fn test_source_file(home: &Path, name: &str) -> SourceFile {
        SourceFile {
            path: home.join(name),
            kind: ScanRootKind::Native,
            mtime_ms: 1_789_000_000_000,
            size_bytes: 1024,
        }
    }

    fn native_source_file(path: &Path) -> SourceFile {
        source_file(path, ScanRootKind::Native)
    }

    fn import_source_file(path: &Path) -> SourceFile {
        source_file(path, ScanRootKind::Import)
    }

    fn write_import_manifest(root: &Path, files: &[&str]) {
        fs::create_dir_all(root).unwrap();
        fs::write(
            root.join(IMPORT_MANIFEST_FILE),
            serde_json::json!({ "files": files }).to_string(),
        )
        .unwrap();
    }

    fn source_file(path: &Path, kind: ScanRootKind) -> SourceFile {
        let size_bytes = fs::metadata(path).map(|meta| meta.len()).unwrap_or(1024);
        SourceFile {
            path: path.to_path_buf(),
            kind,
            mtime_ms: 1_789_000_000_000,
            size_bytes,
        }
    }

    fn sqlite_db_size_bytes(conn: &Connection) -> i64 {
        let page_count: i64 = conn
            .query_row("PRAGMA page_count", [], |row| row.get(0))
            .unwrap();
        let page_size: i64 = conn
            .query_row("PRAGMA page_size", [], |row| row.get(0))
            .unwrap();
        let mut total = page_count * page_size;
        let db_path: Option<String> = conn
            .query_row("PRAGMA database_list", [], |row| row.get(2))
            .ok()
            .filter(|path: &String| !path.trim().is_empty());
        if let Some(db_path) = db_path {
            for suffix in ["-wal", "-shm"] {
                let sidecar = format!("{db_path}{suffix}");
                if let Ok(meta) = fs::metadata(sidecar) {
                    total = total.saturating_add(i64::try_from(meta.len()).unwrap_or(i64::MAX));
                }
            }
        }
        total
    }

