    fn pb_varint(mut value: u64) -> Vec<u8> {
        let mut out = Vec::new();
        while value >= 0x80 {
            out.push((value as u8 & 0x7f) | 0x80);
            value >>= 7;
        }
        out.push(value as u8);
        out
    }

    fn pb_key(field_number: u32, wire_type: u8) -> Vec<u8> {
        pb_varint(((field_number as u64) << 3) | u64::from(wire_type))
    }

    fn pb_varint_field(field_number: u32, value: u64) -> Vec<u8> {
        let mut out = pb_key(field_number, 0);
        out.extend(pb_varint(value));
        out
    }

    fn pb_bytes_field(field_number: u32, bytes: &[u8]) -> Vec<u8> {
        let mut out = pb_key(field_number, 2);
        out.extend(pb_varint(bytes.len() as u64));
        out.extend(bytes);
        out
    }

    fn pb_string_field(field_number: u32, value: &str) -> Vec<u8> {
        pb_bytes_field(field_number, value.as_bytes())
    }

    fn pb_timestamp_ms_field(field_number: u32, timestamp_ms: i64) -> Vec<u8> {
        let seconds = timestamp_ms.div_euclid(1000);
        let nanos = timestamp_ms.rem_euclid(1000) * 1_000_000;
        let mut timestamp = pb_varint_field(1, seconds as u64);
        timestamp.extend(pb_varint_field(2, nanos as u64));
        pb_bytes_field(field_number, &timestamp)
    }

    fn antigravity_fixture_gen_metadata() -> Vec<u8> {
        let mut usage = pb_varint_field(1, 100);
        usage.extend(pb_varint_field(2, 80));
        usage.extend(pb_varint_field(5, 10));
        usage.extend(pb_varint_field(9, 40));
        usage.extend(pb_varint_field(10, 5));
        usage.extend(pb_string_field(11, "agy-response-1"));

        let mut generation = Vec::new();
        generation.extend(pb_timestamp_ms_field(4, 1_781_589_600_000_i64));

        let prompt = pb_string_field(3, "<USER_REQUEST>antigravity prompt");
        let output = pb_string_field(3, "antigravity output");

        let mut chat_model = pb_string_field(19, "gemini-3-pro");
        chat_model.extend(pb_bytes_field(4, &usage));
        chat_model.extend(pb_bytes_field(9, &generation));
        chat_model.extend(pb_bytes_field(2, &prompt));
        chat_model.extend(pb_bytes_field(2, &output));

        pb_bytes_field(1, &chat_model)
    }

