    #[test]
    fn qwen_token_usage_record_fixture_maps_supplemental_runtime_usage() {
        with_home(|home| {
            let path = write_qwen_token_usage_record_fixture(home);

            assert!(
                is_native_file("qwen", &path),
                "qwen native matcher must include runtime usage/token-usage-YYYY-MM.jsonl"
            );
            let result = scan_source_file("qwen", &native_source_file(&path)).unwrap();
            assert_eq!(result.messages.len(), 1);
            let message = &result.messages[0];
            assert_eq!(message.model, "qwen3-coder-plus");
            assert_eq!(message.session_id, "qwen-token-session");
            assert_eq!(message.account, "oauth-personal");
            assert_eq!(message.tokens.input, 66);
            assert_eq!(message.tokens.output, 27);
            assert_eq!(message.tokens.cache_read, 8);
            assert_eq!(message.tokens.reasoning, 5);
            assert_eq!(message.message_count, 1);
        });
    }

    #[test]
    fn kiro_hook_jsonl_maps_official_events_with_local_derived_usage() {
        with_home(|home| {
            let path = home.join(".kiro/hooks/kiro-hooks.jsonl");
            write_lines(
                &path,
                &[
                    serde_json::json!({
                        "hook_event_name": "userPromptSubmit",
                        "session_id": "kiro-hook-session",
                        "cwd": "/tmp/kiro-project",
                        "timestamp": "2026-06-16T14:00:00Z",
                        "prompt": "kiro prompt"
                    }),
                    serde_json::json!({
                        "hook_event_name": "preToolUse",
                        "session_id": "kiro-hook-session",
                        "cwd": "/tmp/kiro-project",
                        "timestamp": "2026-06-16T14:00:01Z",
                        "tool_name": "read_file",
                        "tool_input": {"path": "src/lib.rs"}
                    }),
                    serde_json::json!({
                        "hook_event_name": "preToolUse",
                        "session_id": "kiro-hook-session",
                        "cwd": "/tmp/kiro-project",
                        "timestamp": "2026-06-16T14:00:02Z",
                        "tool_name": "apply_patch",
                        "tool_input": {"path": "src/lib.rs", "old": "old\n", "new": "new\n"}
                    }),
                    serde_json::json!({
                        "hook_event_name": "postToolUse",
                        "session_id": "kiro-hook-session",
                        "cwd": "/tmp/kiro-project",
                        "timestamp": "2026-06-16T14:00:03Z",
                        "tool_name": "read_file",
                        "tool_response": "file content"
                    }),
                    serde_json::json!({
                        "hook_event_name": "stop",
                        "session_id": "kiro-hook-session",
                        "cwd": "/tmp/kiro-project",
                        "timestamp": "2026-06-16T14:00:04Z",
                        "assistant_response": "kiro output"
                    }),
                ],
            );
            assert!(
                is_native_file("kiro", &path),
                "kiro native matcher must include official hook JSONL files"
            );

            let result = scan_source_file("kiro", &native_source_file(&path)).unwrap();
            assert!(
                !result.messages.is_empty(),
                "kiro hook JSONL should emit local derived usage rows"
            );
            assert!(
                result
                    .messages
                    .iter()
                    .all(|message| message.usage_basis == UsageBasis::LocalDerived),
                "kiro hook JSONL usage rows must remain distinguishable from native tokens"
            );
            let event_types = result
                .events
                .iter()
                .map(|event| event.event_type.as_str())
                .collect::<HashSet<_>>();
            for expected in ["prompt", "output", "tool", "tool_result", "edit"] {
                assert!(
                    event_types.contains(expected),
                    "Kiro hook JSONL missing {expected}, got {event_types:?}"
                );
            }
            assert!(result.events.iter().all(|event| {
                event.agent == "kiro"
                    && event.provider == "kiro"
                    && event.session_id == "kiro-hook-session"
            }));

            let journal_dir = home.join("local-sources/kiro");
            fs::create_dir_all(&journal_dir).unwrap();
            write_import_manifest(&journal_dir, &["hook-events.jsonl"]);
            write_lines(
                &journal_dir.join("hook-events.jsonl"),
                &[serde_json::json!({
                    "aitrack": {"schema": 1, "source": "hook-event", "agent": "kiro"},
                    "event": {
                        "hook_event_name": "userPromptSubmit",
                        "session_id": "kiro-local-journal-session",
                        "cwd": "/tmp/kiro-project",
                        "timestamp": "2026-06-16T14:00:05Z",
                        "prompt": "kiro local journal prompt"
                    }
                })],
            );

            let mut conn = open_usage_db().unwrap();
            let report = tokio_test::block_on(scan_into(
                &mut conn,
                UsageScanOptions {
                    tools: vec!["kiro".to_string()],
                    since: None,
                    until: None,
                },
                Some("device-kiro-hooks"),
            ))
            .unwrap();
            assert!(
                report.parsed_messages >= 1,
                "kiro local hook journal should emit local-derived usage rows, report={report:?}"
            );
            assert!(source_rollup_count(&conn, "kiro") >= 1);
            let (tokens_in, tokens_out, message_count) = agent_rollup_totals(&conn, "kiro");
            assert!(
                tokens_in > 0 || tokens_out > 0,
                "kiro local-derived rollup should include text-derived tokens"
            );
            assert!(message_count >= 1);
            assert!(
                report.monitoring_events_parsed >= 6,
                "kiro hook scan should include native and local-journal monitoring events, report={report:?}"
            );
            let event_types = monitoring_event_types_for_agent("kiro");
            for expected in ["prompt", "output", "tool", "tool_result", "edit"] {
                assert!(
                    event_types.contains(expected),
                    "Kiro inserted monitoring records missing {expected}, got {event_types:?}"
                );
            }
        });
    }

    #[test]
    fn warp_sqlite_reader_maps_agent_conversation_usage_and_task_proto() {
        with_home(|home| {
            let path = write_realistic_matrix_fixture(home, "warp");

            let warp_spec = agent::local_source_specs()
                .iter()
                .find(|spec| spec.agent == "warp" && spec.label == "warp-sqlite")
                .expect("warp/warp-sqlite source spec missing");
            assert!(
                warp_spec.capabilities.prompt_input
                    && warp_spec.capabilities.assistant_output
                    && warp_spec.capabilities.tool_call
                    && warp_spec.capabilities.tool_result
                    && warp_spec.capabilities.session_context
                    && warp_spec.capabilities.time_context
                    && warp_spec.capabilities.model_provider_context
                    && warp_spec.capabilities.cost_usage
                    && warp_spec.capabilities.edit_diff,
                "warp/warp-sqlite must keep typed sqlite/protobuf transcript, cost, and edit coverage enabled"
            );
            assert!(
                !warp_spec.capabilities.token_usage,
                "warp/warp-sqlite only exposes aggregate/category usage, not stable token buckets"
            );

            assert!(
                is_native_file("warp", &path),
                "warp native matcher must include warp.sqlite"
            );
            let result = scan_source_file("warp", &native_source_file(&path)).unwrap();

            assert_eq!(result.messages.len(), 1);
            let usage = &result.messages[0];
            assert_eq!(usage.agent, "warp");
            assert_eq!(usage.provider, "warp");
            assert_eq!(usage.model, "claude-sonnet-4");
            assert_eq!(usage.session_id, "warp-conversation");
            assert_eq!(usage.tokens.input, 140);
            assert_eq!(usage.tokens.output, 0);
            assert_eq!(usage.tokens.cache_read, 0);
            assert_eq!(usage.tokens.cache_write, 0);
            assert_eq!(usage.tokens.reasoning, 0);
            assert!((usage.source_cost - 0.02).abs() < 0.0001);

            let event_types = result
                .events
                .iter()
                .map(|event| event.event_type.as_str())
                .collect::<HashSet<_>>();
            for expected in ["prompt", "output", "tool", "tool_result", "edit"] {
                assert!(
                    event_types.contains(expected),
                    "Warp task proto missing {expected}, got {event_types:?}"
                );
            }
            assert!(result.events.iter().any(|event| {
                event.event_type == "prompt"
                    && event.prompt_text.as_deref() == Some("warp prompt")
                    && event.session_id == "warp-conversation"
                    && event.model.as_deref() == Some("claude-sonnet-4")
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("\"workspace\":\"/tmp/project\""))
            }));
            assert!(result.events.iter().any(|event| {
                event.event_type == "output"
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("warp output"))
            }));
            assert!(result.events.iter().any(|event| {
                event.event_type == "tool"
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("read_files"))
            }));
            assert!(result.events.iter().any(|event| {
                event.event_type == "tool_result"
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("file content"))
            }));
        });
    }

