    #[test]
    fn mux_official_session_files_map_typed_local_fields() {
        with_home(|home| {
            let session_dir = home.join(".mux/sessions/workspace-one");
            let usage_path = session_dir.join("session-usage.json");
            write_json_value(
                &usage_path,
                serde_json::json!({
                    "version": 1,
                    "byModel": {
                        "anthropic:claude-opus-4-6": {
                            "input": {"tokens": 100, "cost_usd": 0.01},
                            "cached": {"tokens": 50, "cost_usd": 0.005},
                            "cacheCreate": {"tokens": 20, "cost_usd": 0.002},
                            "output": {"tokens": 30, "cost_usd": 0.003},
                            "reasoning": {"tokens": 7, "cost_usd": 0.001}
                        }
                    },
                    "lastRequest": {"timestamp": 1_781_589_600_000_i64}
                }),
            );

            let chat_path = session_dir.join("chat.jsonl");
            write_lines(
                &chat_path,
                &[
                    serde_json::json!({
                        "id": "mux-user",
                        "sessionId": "mux-session",
                        "role": "user",
                        "createdAt": 1_781_589_600_000_i64,
                        "parts": [{"type": "text", "text": "mux prompt"}],
                        "metadata": {
                            "cwd": "/tmp/mux-project",
                            "workspace": "workspace-one",
                            "model": "claude-opus-4-6",
                            "routeProvider": "anthropic"
                        }
                    }),
                    serde_json::json!({
                        "id": "mux-assistant",
                        "sessionId": "mux-session",
                        "role": "assistant",
                        "createdAt": 1_781_589_601_000_i64,
                        "parts": [
                            {"type": "text", "text": "mux output"},
                            {"type": "reasoning", "text": "mux reasoning"},
                            {"type": "file", "path": "src/lib.rs", "text": "fn main() {}"},
                            {
                                "type": "dynamic-tool",
                                "state": "output-available",
                                "toolCallId": "tool-1",
                                "toolName": "read_file",
                                "input": {"path": "src/lib.rs"},
                                "output": "file content"
                            }
                        ],
                        "metadata": {
                            "cwd": "/tmp/mux-project",
                            "workspace": "workspace-one",
                            "model": "claude-opus-4-6",
                            "routeProvider": "anthropic",
                            "usage": {
                                "inputTokens": 100,
                                "outputTokens": 30,
                                "reasoningTokens": 7
                            }
                        }
                    }),
                ],
            );

            let archive_path = session_dir.join("chat-archive.jsonl");
            write_lines(
                &archive_path,
                &[serde_json::json!({
                    "id": "mux-archive-assistant",
                    "sessionId": "mux-session",
                    "role": "assistant",
                    "createdAt": 1_781_589_602_000_i64,
                    "parts": [{"type": "text", "text": "mux archived output"}],
                    "metadata": {
                        "cwd": "/tmp/mux-project",
                        "workspace": "workspace-one",
                        "model": "claude-opus-4-6",
                        "routeProvider": "anthropic"
                    }
                })],
            );

            let partial_path = session_dir.join("partial.json");
            write_json_value(
                &partial_path,
                serde_json::json!({
                    "id": "mux-partial-assistant",
                    "sessionId": "mux-session",
                    "role": "assistant",
                    "createdAt": 1_781_589_603_000_i64,
                    "parts": [{"type": "text", "text": "mux partial output"}],
                    "metadata": {
                        "cwd": "/tmp/mux-project",
                        "workspace": "workspace-one",
                        "model": "claude-opus-4-6",
                        "routeProvider": "anthropic"
                    }
                }),
            );
            let devtools_path = session_dir.join("devtools.jsonl");

            assert!(is_native_file("mux", &chat_path));
            assert!(is_native_file("mux", &archive_path));
            assert!(is_native_file("mux", &partial_path));
            assert!(is_native_file("mux", &usage_path));
            assert!(!is_native_file("mux", &devtools_path));

            let result = scan_source_file("mux", &native_source_file(&chat_path)).unwrap();
            let usage_result = scan_source_file("mux", &native_source_file(&usage_path)).unwrap();
            let archive_result =
                scan_source_file("mux", &native_source_file(&archive_path)).unwrap();
            let partial_result =
                scan_source_file("mux", &native_source_file(&partial_path)).unwrap();

            assert_eq!(result.messages.len(), 1);
            let usage = &result.messages[0];
            assert_eq!(usage.session_id, "mux-session");
            assert_eq!(usage.model, "claude-opus-4-6");
            assert_eq!(usage.provider, "anthropic");
            assert_eq!(usage.tokens.input, 100);
            assert_eq!(usage.tokens.output, 30);
            assert_eq!(usage.tokens.reasoning, 7);
            assert_eq!(usage_result.messages.len(), 1);
            assert_eq!(usage_result.messages[0].tokens.cache_read, 50);
            assert_eq!(usage_result.messages[0].tokens.cache_write, 20);
            assert!(!archive_result.events.is_empty());
            assert!(partial_result.events.iter().any(|event| {
                event.event_type == "output"
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("mux partial output"))
            }));

            let event_types = result
                .events
                .iter()
                .map(|event| event.event_type.as_str())
                .collect::<HashSet<_>>();
            for expected in ["prompt", "output", "tool", "tool_result"] {
                assert!(
                    event_types.contains(expected),
                    "missing {expected}, got {event_types:?}"
                );
            }
            assert!(result.events.iter().any(|event| {
                event.event_type == "output"
                    && event.metadata.as_deref().is_some_and(|metadata| {
                        metadata.contains("agent_reasoning") && metadata.contains("mux reasoning")
                    })
            }));
            assert!(result
                .events
                .iter()
                .all(|event| event.session_id == "mux-session"));
            assert!(result.events.iter().all(|event| {
                event
                    .metadata
                    .as_ref()
                    .is_some_and(|metadata| metadata.contains("\"workspace\":\"/tmp/mux-project\""))
            }));
            let tool_event = result
                .events
                .iter()
                .find(|event| event.event_type == "tool")
                .expect("dynamic-tool input should emit a tool call");
            assert!(tool_event
                .metadata
                .as_ref()
                .is_some_and(|metadata| metadata.contains("src/lib.rs")));
            let result_event = result
                .events
                .iter()
                .find(|event| event.event_type == "tool_result")
                .expect("dynamic-tool output should emit a tool result");
            assert!(result_event
                .metadata
                .as_ref()
                .is_some_and(|metadata| metadata.contains("file content")));
        });
    }

