    #[test]
    fn amp_stream_reader_maps_stream_json_usage_and_blocks() {
        with_home(|home| {
            let path = home.join(".amp/sessions/session-amp.jsonl");
            write_lines(
                &path,
                &[
                    serde_json::json!({"type": "system", "subtype": "init", "session_id": "amp-session", "cwd": "/tmp/project"}),
                    serde_json::json!({
                        "type": "user",
                        "session_id": "amp-session",
                        "message": {"role": "user", "content": [{"type": "text", "text": "amp prompt"}]},
                        "timestamp": "2026-06-16T14:00:00Z"
                    }),
                    serde_json::json!({
                        "type": "assistant",
                        "session_id": "amp-session",
                        "message": {
                            "role": "assistant",
                            "content": [
                                {"type": "text", "text": "amp output"},
                                {"type": "tool_use", "id": "tool-1", "name": "read_file", "input": {"path": "src/lib.rs"}},
                                {"type": "tool_use", "id": "tool-edit", "name": "apply_patch", "input": {"path": "src/lib.rs", "old": "old\n", "new": "new\n"}}
                            ],
                            "usage": {"input_tokens": 100, "output_tokens": 45, "cache_read_input_tokens": 8, "cache_creation_input_tokens": 4}
                        },
                        "timestamp": "2026-06-16T14:00:01Z"
                    }),
                    serde_json::json!({
                        "type": "user",
                        "session_id": "amp-session",
                        "message": {"role": "user", "content": [{"type": "tool_result", "tool_use_id": "tool-1", "content": "file content"}]},
                        "timestamp": "2026-06-16T14:00:01Z"
                    }),
                    serde_json::json!({
                        "type": "result",
                        "session_id": "amp-session",
                        "result": "amp output",
                        "usage": {"input_tokens": 100, "output_tokens": 45, "cache_read_input_tokens": 8, "cache_creation_input_tokens": 4},
                        "timestamp": "2026-06-16T14:00:01Z"
                    }),
                ],
            );

            let result = scan_source_file("amp", &native_source_file(&path)).unwrap();
            assert!(
                result
                    .messages
                    .iter()
                    .any(|message| message.usage_basis == UsageBasis::LocalDerived),
                "amp prompt/output/tool text should emit distinguishable local-derived usage rows"
            );
            let usage = result
                .messages
                .iter()
                .find(|message| {
                    message.usage_basis == UsageBasis::Native
                        && message.tokens.input == 100
                        && message.tokens.output == 45
                })
                .expect("amp stream fixture should preserve native usage");
            assert_eq!(usage.session_id, "amp-session");
            assert_eq!(usage.tokens.input, 100);
            assert_eq!(usage.tokens.output, 45);
            assert_eq!(usage.tokens.cache_read, 8);
            assert_eq!(usage.tokens.cache_write, 4);
            let event_types = result
                .events
                .iter()
                .map(|event| event.event_type.as_str())
                .collect::<HashSet<_>>();
            for expected in ["prompt", "output", "tool", "tool_result", "edit"] {
                assert!(
                    event_types.contains(expected),
                    "missing {expected}, got {event_types:?}"
                );
            }
        });
    }

    #[test]
    fn amp_default_root_scan_into_maps_stream_json_usage() {
        with_home(|home| {
            let path = write_matrix_fixture(home, "amp");
            let mut collector = FileCollector::default();
            for root in scan_roots(home, "amp") {
                collect_supported_files(
                    "amp",
                    &root,
                    &FileScanPlan::unbounded_for_tests(),
                    &mut collector,
                );
            }
            assert!(
                collector.files.iter().any(|file| file.path == path),
                "amp default roots did not collect {}, collected={:?}",
                path.display(),
                collector
                    .files
                    .iter()
                    .map(|file| file.path.display().to_string())
                    .collect::<Vec<_>>()
            );
            let mut conn = open_usage_db().unwrap();
            let report = tokio_test::block_on(scan_into(
                &mut conn,
                UsageScanOptions {
                    tools: vec!["amp".to_string()],
                    since: None,
                    until: None,
                },
                Some("device-amp-default"),
            ))
            .unwrap();
            assert!(
                report.parsed_messages >= 1,
                "amp default scan should produce usage, report={report:?}"
            );
            assert!(
                report.monitoring_events_parsed >= 5,
                "amp default scan should produce full monitoring, report={report:?}"
            );
        });
    }

