    #[test]
    fn openclaw_sessions_store_resolves_session_file_usage() {
        with_home(|home| {
            let path = home.join(".openclaw/agents/main/sessions/sessions.json");
            let transcript = path.parent().unwrap().join("session-openclaw.jsonl");
            write_json_value(
                &path,
                serde_json::json!({
                    "agent:main": {
                        "sessionId": "openclaw-session",
                        "sessionFile": transcript.to_string_lossy(),
                        "lastAccountId": "openclaw-account",
                        "origin": {"accountId": "origin-account"},
                        "updatedAt": "2026-06-16T14:00:01Z",
                        "chatType": "agent",
                        "channel": "main"
                    }
                }),
            );
            write_lines(
                &transcript,
                &[
                    serde_json::json!({"type": "session", "id": "openclaw-session", "cwd": "/tmp/project", "timestamp": "2026-06-16T14:00:00Z"}),
                    serde_json::json!({"type": "model_change", "modelId": "gpt-5", "provider": "openai", "timestamp": "2026-06-16T14:00:00Z"}),
                    serde_json::json!({
                        "type": "message",
                        "sessionId": "openclaw-session",
                        "timestamp": "2026-06-16T14:00:01Z",
                        "message": {
                            "role": "assistant",
                            "content": [
                                {"type": "text", "text": "openclaw output"},
                                {"type": "toolCall", "id": "tool-edit", "name": "edit", "arguments": {"path": "src/lib.rs", "edits": [{"oldText": "old\n", "newText": "new\n"}]}}
                            ],
                            "usage": {"input": 100, "output": 40, "cacheReadTokens": 8, "cacheWriteTokens": 3, "cost": {"total": 0.03}},
                            "model": "gpt-5",
                            "provider": "openai"
                        }
                    }),
                ],
            );

            let result = scan_source_file("openclaw", &native_source_file(&path)).unwrap();
            assert_eq!(result.messages.len(), 1);
            let usage = &result.messages[0];
            assert_eq!(usage.session_id, "openclaw-session");
            assert_eq!(usage.provider, "openai");
            assert_eq!(usage.model, "gpt-5");
            assert_eq!(usage.account, "openclaw-account");
            assert_eq!(usage.tokens.input, 100);
            assert_eq!(usage.tokens.output, 40);
            assert_eq!(usage.tokens.cache_read, 8);
            assert_eq!(usage.tokens.cache_write, 3);
            let event_types = result
                .events
                .iter()
                .map(|event| event.event_type.as_str())
                .collect::<HashSet<_>>();
            assert!(
                event_types.contains("output"),
                "missing output: {event_types:?}"
            );
            assert!(
                event_types.contains("edit"),
                "missing edit: {event_types:?}"
            );
        });
    }

