    #[test]
    fn copilot_chat_session_reader_unwraps_v_payload() {
        with_home(|home| {
            let path = home
                .join("Library/Application Support/Code/User/workspaceStorage")
                .join("copilot-wrapper/chatSessions/copilot-wrapper.jsonl");
            let session_payload = |session_id: &str, prompt: &str, output: &str| {
                serde_json::json!({
                    "sessionId": session_id,
                    "creationDate": "2026-06-16T14:00:00Z",
                    "lastMessageDate": "2026-06-16T14:00:01Z",
                    "inputState": {"selectedModel": "gpt-5"},
                    "requests": [
                        {
                            "timestamp": "2026-06-16T14:00:01Z",
                            "modelId": "gpt-5",
                            "promptTokens": 101,
                            "completionTokens": 41,
                            "cacheReadTokens": 9,
                            "message": {
                                "text": prompt,
                                "parts": [{"kind": "text", "text": prompt}]
                            },
                            "response": [{"value": output}],
                            "result": {
                                "toolInvocationSerialized": {
                                    "toolName": "read_file",
                                    "toolCallId": "copilot-wrapper-tool-read",
                                    "args": {"path": "src/lib.rs"}
                                },
                                "textEditGroup": {
                                    "uri": "src/lib.rs",
                                    "edits": [{"oldText": "old\n", "newText": "new\n"}]
                                }
                            }
                        }
                    ]
                })
            };
            write_lines(
                &path,
                &[
                    serde_json::json!({
                        "kind": "chatSession",
                        "v": session_payload(
                            "copilot-wrapper-kind-v",
                            "wrapped prompt",
                            "wrapped output"
                        )
                    }),
                    serde_json::json!({
                        "k": "copilot-wrapper-key",
                        "kind": "chatSession",
                        "v": session_payload(
                            "copilot-wrapper-k-kind-v",
                            "wrapped k prompt",
                            "wrapped k output"
                        )
                    }),
                ],
            );

            let result = scan_source_file("copilot", &native_source_file(&path)).unwrap();
            let assert_wrapper = |session_id: &str, prompt: &str, output: &str| {
                assert!(
                    result.messages.iter().any(|message| {
                        message.session_id == session_id
                            && message.tokens.input == 101
                            && message.tokens.output == 41
                            && message.tokens.cache_read == 9
                    }),
                    "Copilot wrapper {session_id} should expose token usage: {:?}",
                    result.messages
                );
                assert!(
                    result.events.iter().any(|event| {
                        event.session_id == session_id
                            && event.event_type == "prompt"
                            && event.prompt_text.as_deref() == Some(prompt)
                    }),
                    "Copilot wrapper {session_id} should expose user prompt: {:?}",
                    result.events
                );
                assert!(
                    result.events.iter().any(|event| {
                        event.session_id == session_id
                            && event.event_type == "output"
                            && event
                                .metadata
                                .as_deref()
                                .is_some_and(|metadata| metadata.contains(output))
                    }),
                    "Copilot wrapper {session_id} should expose assistant output: {:?}",
                    result.events
                );
                for expected in ["tool", "edit"] {
                    assert!(
                        result.events.iter().any(|event| {
                            event.session_id == session_id && event.event_type == expected
                        }),
                        "Copilot wrapper {session_id} missing {expected}: {:?}",
                        result.events
                    );
                }
            };
            assert_wrapper("copilot-wrapper-kind-v", "wrapped prompt", "wrapped output");
            assert_wrapper(
                "copilot-wrapper-k-kind-v",
                "wrapped k prompt",
                "wrapped k output",
            );
        });
    }

