    #[test]
    fn copilot_official_runtime_events_map_capture_fields() {
        with_home(|home| {
            let path = home.join(".copilot/session-state/copilot-official-session/events.jsonl");
            write_lines(
                &path,
                &[
                    serde_json::json!({
                        "event": "session.context_changed",
                        "timestamp": "2026-06-16T14:00:00Z",
                        "session_id": "copilot-official-session",
                        "model": "gpt-5",
                        "cwd": "/tmp/copilot-workspace",
                        "gitRoot": "/tmp/copilot-workspace",
                        "repository": "https://github.com/example/project",
                        "branch": "main"
                    }),
                    serde_json::json!({
                        "event": "user.message",
                        "timestamp": "2026-06-16T14:00:01Z",
                        "session_id": "copilot-official-session",
                        "model": "gpt-5",
                        "content": [{"type": "text", "text": "official copilot prompt"}]
                    }),
                    serde_json::json!({
                        "event": "assistant.message_delta",
                        "timestamp": "2026-06-16T14:00:02Z",
                        "session_id": "copilot-official-session",
                        "deltaContent": "official copilot output"
                    }),
                    serde_json::json!({
                        "event": "tool.execution_start",
                        "timestamp": "2026-06-16T14:00:03Z",
                        "session_id": "copilot-official-session",
                        "id": "tool-edit",
                        "name": "apply_patch",
                        "input": {"path": "src/lib.rs", "old": "old\n", "new": "new\n"}
                    }),
                    serde_json::json!({
                        "event": "tool.execution_complete",
                        "timestamp": "2026-06-16T14:00:04Z",
                        "session_id": "copilot-official-session",
                        "id": "tool-edit",
                        "result": {"output": "patch applied", "file": "src/lib.rs"}
                    }),
                    serde_json::json!({
                        "event": "assistant.usage",
                        "timestamp": "2026-06-16T14:00:05Z",
                        "session_id": "copilot-official-session",
                        "model": "gpt-5",
                        "usage": {
                            "input_tokens": 31,
                            "output_tokens": 17,
                            "cache_read_tokens": 5,
                            "reasoning_tokens": 3,
                            "cost": 0.0042
                        }
                    }),
                    serde_json::json!({
                        "event": "session.shutdown",
                        "timestamp": "2026-06-16T14:00:06Z",
                        "session_id": "copilot-official-session",
                        "codeChanges": [
                            {
                                "file": "src/lib.rs",
                                "diff": "--- a/src/lib.rs\n+++ b/src/lib.rs\n@@\n-old\n+new\n"
                            }
                        ]
                    }),
                ],
            );

            assert!(is_native_file("copilot", &path));
            let result = scan_source_file("copilot", &native_source_file(&path)).unwrap();
            assert_eq!(result.messages.len(), 1);
            let usage = &result.messages[0];
            assert_eq!(usage.session_id, "copilot-official-session");
            assert_eq!(usage.provider, "github");
            assert_eq!(usage.model, "gpt-5");
            assert_eq!(usage.tokens.input, 31);
            assert_eq!(usage.tokens.output, 17);
            assert_eq!(usage.tokens.cache_read, 5);
            assert_eq!(usage.tokens.reasoning, 3);
            assert_eq!(usage.source_cost, 0.0042);

            let event_types = result
                .events
                .iter()
                .map(|event| event.event_type.as_str())
                .collect::<HashSet<_>>();
            for expected in ["prompt", "output", "tool", "tool_result", "edit"] {
                assert!(
                    event_types.contains(expected),
                    "missing {expected}, got {event_types:?}: {:?}",
                    result.events
                );
            }
            assert!(result.events.iter().any(|event| {
                event.session_id == "copilot-official-session"
                    && event.event_type == "prompt"
                    && event.prompt_text.as_deref() == Some("official copilot prompt")
                    && event.branch == "main"
            }));
            assert!(result.events.iter().any(|event| {
                event.session_id == "copilot-official-session"
                    && event.event_type == "output"
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("official copilot output"))
            }));
            assert!(result.events.iter().any(|event| {
                event.session_id == "copilot-official-session"
                    && event.event_type == "edit"
                    && event.file_path == "src/lib.rs"
                    && event.added_lines == 1
                    && event.removed_lines == 1
            }));
        });
    }

    #[test]
    fn codebuff_chat_message_maps_real_usage_fields_without_inferring_credits() {
        with_home(|home| {
            let path = home.join(
                ".config/manicode/projects/project-one/chats/2026-06-16T14-00-00.000Z/chat-messages.json",
            );
            write_json_value(
                &path.parent().unwrap().join("run-state.json"),
                serde_json::json!({
                    "traceSessionId": "codebuff-usage-session",
                    "sessionState": {"cwd": "/tmp/project"}
                }),
            );
            write_json_value(
                &path,
                serde_json::json!([
                    {
                        "id": "codebuff-credits-only",
                        "variant": "ai",
                        "timestamp": "2026-06-16T14:00:00Z",
                        "content": "credits only output",
                        "credits": 0.1,
                        "blocks": [
                            {"type": "text", "content": "credits only block"}
                        ]
                    },
                    {
                        "id": "codebuff-real-usage",
                        "variant": "ai",
                        "timestamp": "2026-06-16T14:00:01Z",
                        "content": "usage output",
                        "credits": 0.2,
                        "providerOptions": {
                            "usage": {
                                "inputTokens": 44,
                                "outputTokens": 17,
                                "cacheReadTokens": 6,
                                "reasoningTokens": 3
                            }
                        },
                        "blocks": [
                            {
                                "type": "tool",
                                "toolCallId": "tool-1",
                                "toolName": "read_file",
                                "input": {"path": "src/lib.rs"},
                                "output": "file content"
                            }
                        ]
                    }
                ]),
            );

            let result = scan_source_file("codebuff", &native_source_file(&path)).unwrap();
            assert_eq!(result.messages.len(), 2);
            let credits_only = result
                .messages
                .iter()
                .find(|message| (message.source_cost - 0.1).abs() < 0.0001)
                .expect("credits-only usage row missing");
            assert_eq!(credits_only.tokens.input, 0);
            assert_eq!(credits_only.tokens.output, 0);
            assert_eq!(credits_only.tokens.cache_read, 0);
            assert_eq!(credits_only.tokens.cache_write, 0);
            assert_eq!(credits_only.tokens.reasoning, 0);

            let real_usage = result
                .messages
                .iter()
                .find(|message| (message.source_cost - 0.2).abs() < 0.0001)
                .expect("real usage row missing");
            assert_eq!(real_usage.tokens.input, 44);
            assert_eq!(real_usage.tokens.output, 17);
            assert_eq!(real_usage.tokens.cache_read, 6);
            assert_eq!(real_usage.tokens.reasoning, 3);
        });
    }

