    #[test]
    fn codebuff_chat_message_does_not_double_count_run_state_when_messages_have_cost() {
        with_home(|home| {
            let path = home.join(
                ".config/manicode/projects/project-one/chats/2026-06-16T15-30-00.000Z/chat-messages.json",
            );
            write_json_value(
                &path.parent().unwrap().join("run-state.json"),
                serde_json::json!({
                    "traceSessionId": "codebuff-message-cost-session",
                    "sessionState": {
                        "mainAgentState": {
                            "creditsUsed": 9.0,
                            "directCreditsUsed": 8.0,
                            "fileContext": {"cwd": "/tmp/project"}
                        }
                    }
                }),
            );
            write_json_value(
                &path,
                serde_json::json!([
                    {
                        "id": "codebuff-message-cost-one",
                        "variant": "ai",
                        "timestamp": "2026-06-16T15:30:00Z",
                        "content": "first output",
                        "credits": 0.2
                    },
                    {
                        "id": "codebuff-message-cost-two",
                        "variant": "ai",
                        "timestamp": "2026-06-16T15:30:01Z",
                        "content": "second output",
                        "providerOptions": {"usage": {"credits": 0.3}}
                    }
                ]),
            );

            let result = scan_source_file("codebuff", &native_source_file(&path)).unwrap();
            assert_eq!(result.messages.len(), 2);
            let total_cost: f64 = result
                .messages
                .iter()
                .map(|message| message.source_cost)
                .sum();
            assert!((total_cost - 0.5).abs() < 0.0001);
            assert!(result
                .messages
                .iter()
                .all(|message| (message.source_cost - 9.0).abs() > 0.0001));
        });
    }

    #[test]
    fn codebuff_tool_blocks_extract_official_nested_edit_inputs() {
        with_home(|home| {
            let path = home.join(
                ".config/manicode/projects/project-one/chats/2026-06-16T16-00-00.000Z/chat-messages.json",
            );
            write_json_value(
                &path.parent().unwrap().join("run-state.json"),
                serde_json::json!({
                    "traceSessionId": "codebuff-edit-session",
                    "sessionState": {
                        "mainAgentState": {
                            "creditsUsed": 0.05,
                            "fileContext": {"cwd": "/tmp/project"}
                        }
                    }
                }),
            );
            write_json_value(
                &path,
                serde_json::json!([
                    {
                        "id": "codebuff-edit-msg",
                        "variant": "ai",
                        "timestamp": "2026-06-16T16:00:00Z",
                        "content": "editing",
                        "blocks": [
                            {
                                "type": "tool",
                                "toolCallId": "apply-nested",
                                "toolName": "apply_patch",
                                "input": {
                                    "operation": {
                                        "path": "src/app.rs",
                                        "diff": "@@ -1 +1 @@\n-old\n+new\n"
                                    }
                                },
                                "outputRaw": {"ok": true}
                            },
                            {
                                "type": "tool",
                                "toolCallId": "replace-nested",
                                "toolName": "str_replace",
                                "input": {
                                    "path": "src/lib.rs",
                                    "replacements": [
                                        {
                                            "oldString": "old value",
                                            "newString": "new value"
                                        }
                                    ]
                                },
                                "output": "replaced"
                            },
                            {
                                "type": "tool",
                                "toolCallId": "write-file",
                                "toolName": "write_file",
                                "input": {
                                    "path": "src/new.rs",
                                    "content": "new file contents"
                                },
                                "output": "wrote"
                            },
                            {
                                "type": "tool",
                                "toolCallId": "propose-edit",
                                "toolName": "propose_file_change",
                                "input": {
                                    "path": "src/proposed.rs",
                                    "diff": "@@ -2 +2 @@\n-before\n+after\n"
                                },
                                "output": "proposed"
                            }
                        ]
                    }
                ]),
            );

            let result = scan_source_file("codebuff", &native_source_file(&path)).unwrap();
            let edit_events = result
                .events
                .iter()
                .filter(|event| event.event_type == "edit")
                .collect::<Vec<_>>();
            assert_eq!(edit_events.len(), 4, "events={:?}", result.events);
            assert!(edit_events.iter().any(|event| {
                event.file_path == "src/app.rs"
                    && event
                        .diff_hunk
                        .as_deref()
                        .is_some_and(|diff| diff.contains("-old"))
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("operation"))
            }));
            assert!(edit_events.iter().any(|event| {
                event.file_path == "src/lib.rs"
                    && event.added_lines > 0
                    && event.removed_lines > 0
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("replacements"))
            }));
            assert!(edit_events.iter().any(|event| {
                event.file_path == "src/new.rs"
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("new file contents"))
            }));
            assert!(edit_events.iter().any(|event| {
                event.file_path == "src/proposed.rs"
                    && event
                        .diff_hunk
                        .as_deref()
                        .is_some_and(|diff| diff.contains("-before"))
            }));
        });
    }

