    #[test]
    fn derived_usage_rollups_keep_native_and_local_derived_basis_separate_in_payload() {
        with_home(|home| {
            let mut conn = open_usage_db().unwrap();
            let file = test_source_file(home, "sources/codex/basis.jsonl");
            let mut native = make_message(1);
            native.tokens.input = 10;
            native.tokens.output = 5;
            native.usage_basis = UsageBasis::Native;
            let mut derived = make_message(2);
            derived.tokens.input = 3;
            derived.tokens.output = 7;
            derived.usage_basis = UsageBasis::LocalDerived;

            assert_eq!(
                replace_rollup_source(&mut conn, "codex", &file, &[native, derived]).unwrap(),
                2
            );
            assert_eq!(enqueue_dirty_rollups(&conn, "device-basis").unwrap(), 2);

            let rollup_rows: i64 = conn
                .query_row(
                    "SELECT COUNT(*) FROM usage_daily_model_rollups
                     WHERE agent = 'codex' AND model = 'gpt-5-20260101' AND account = 'local'",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(rollup_rows, 2);

            let outbox = fetch_pending_outbox(&conn).unwrap().remove(0);
            let payload: RollupPayload = serde_json::from_str(&outbox.payload_json).unwrap();
            let bases = payload
                .items
                .iter()
                .map(|item| item.usage_basis.as_str())
                .collect::<HashSet<_>>();
            assert_eq!(bases, HashSet::from(["native", "local_derived"]));
            assert!(outbox.payload_json.contains("\"usage_basis\":\"native\""));
            assert!(outbox
                .payload_json
                .contains("\"usage_basis\":\"local_derived\""));
        });
    }

    #[test]
    fn usage_basis_migration_rebuilds_old_rollup_unique_constraints() {
        with_home(|home| {
            let path = usage_db_path();
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            let conn = Connection::open(&path).unwrap();
            conn.execute_batch(
                r#"
                CREATE TABLE usage_daily_model_rollups (
                  id INTEGER PRIMARY KEY AUTOINCREMENT,
                  device_id TEXT NOT NULL,
                  day TEXT NOT NULL,
                  agent TEXT NOT NULL,
                  model TEXT NOT NULL,
                  account TEXT NOT NULL DEFAULT '',
                  tokens_in INTEGER NOT NULL DEFAULT 0,
                  tokens_out INTEGER NOT NULL DEFAULT 0,
                  tokens_cache_read INTEGER NOT NULL DEFAULT 0,
                  tokens_cache_write INTEGER NOT NULL DEFAULT 0,
                  tokens_reasoning INTEGER NOT NULL DEFAULT 0,
                  message_count INTEGER NOT NULL DEFAULT 0,
                  source_cost REAL NOT NULL DEFAULT 0,
                  usage_basis TEXT NOT NULL DEFAULT 'native',
                  dirty INTEGER NOT NULL DEFAULT 1,
                  uploaded_at TEXT,
                  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
                  UNIQUE(device_id, day, agent, model, account)
                );
                CREATE TABLE usage_rollup_sources (
                  id INTEGER PRIMARY KEY AUTOINCREMENT,
                  tool TEXT NOT NULL,
                  path TEXT NOT NULL,
                  day TEXT NOT NULL,
                  agent TEXT NOT NULL,
                  model TEXT NOT NULL,
                  account TEXT NOT NULL DEFAULT '',
                  tokens_in INTEGER NOT NULL DEFAULT 0,
                  tokens_out INTEGER NOT NULL DEFAULT 0,
                  tokens_cache_read INTEGER NOT NULL DEFAULT 0,
                  tokens_cache_write INTEGER NOT NULL DEFAULT 0,
                  tokens_reasoning INTEGER NOT NULL DEFAULT 0,
                  message_count INTEGER NOT NULL DEFAULT 0,
                  source_cost REAL NOT NULL DEFAULT 0,
                  usage_basis TEXT NOT NULL DEFAULT 'native',
                  size_bytes INTEGER NOT NULL DEFAULT 0,
                  mtime_ms INTEGER NOT NULL DEFAULT 0,
                  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
                  UNIQUE(tool, path, day, agent, model, account)
                );
                "#,
            )
            .unwrap();
            drop(conn);

            let mut conn = open_usage_db().unwrap();
            let file = test_source_file(home, "sources/codex/legacy-basis.jsonl");
            let mut native = make_message(1);
            native.tokens.input = 10;
            native.tokens.output = 5;
            native.usage_basis = UsageBasis::Native;
            let mut derived = make_message(2);
            derived.tokens.input = 3;
            derived.tokens.output = 7;
            derived.usage_basis = UsageBasis::LocalDerived;

            assert_eq!(
                replace_rollup_source(&mut conn, "codex", &file, &[native, derived]).unwrap(),
                2
            );

            let (source_rows, rollup_rows): (i64, i64) = conn
                .query_row(
                    "SELECT
                       (SELECT COUNT(*) FROM usage_rollup_sources
                        WHERE tool = 'codex' AND usage_basis IN ('native', 'local_derived')),
                       (SELECT COUNT(*) FROM usage_daily_model_rollups
                        WHERE agent = 'codex' AND usage_basis IN ('native', 'local_derived'))",
                    [],
                    |row| Ok((row.get(0)?, row.get(1)?)),
                )
                .unwrap();
            assert_eq!((source_rows, rollup_rows), (2, 2));
        });
    }

