    #[test]
    fn source_rollup_keeps_database_bounded_for_many_messages() {
        with_home(|home| {
            let mut conn = open_usage_db().unwrap();
            let file = test_source_file(home, "sources/codex/bulk.jsonl");
            let messages = (0..10_000)
                .map(|seed| {
                    let mut msg = make_message(seed);
                    msg.session_id = format!("bulk-session-{seed}");
                    msg.dedup_key = format!("bulk-dedup-{seed}");
                    msg.tokens.input = 1;
                    msg.tokens.output = 2;
                    msg.tokens.cache_read = 0;
                    msg.tokens.cache_write = 0;
                    msg.tokens.reasoning = 0;
                    msg.source_cost = 0.0;
                    msg
                })
                .collect::<Vec<_>>();

            assert_eq!(
                replace_rollup_source(&mut conn, "codex", &file, &messages).unwrap(),
                1
            );

            assert_eq!(usage_session_count(&conn, "codex"), 0);
            assert_eq!(source_rollup_count(&conn, "codex"), 1);
            assert_eq!(
                agent_rollup_totals(&conn, "codex"),
                (10_000, 20_000, 10_000)
            );
            let db_size = sqlite_db_size_bytes(&conn);
            assert!(
                db_size < 1_000_000,
                "usage.sqlite should stay bounded for aggregated sources, got {db_size} bytes"
            );

            let replacement = (0..5_000)
                .map(|seed| {
                    let mut msg = make_message(seed);
                    msg.session_id = format!("replacement-session-{seed}");
                    msg.dedup_key = format!("replacement-dedup-{seed}");
                    msg.tokens.input = 3;
                    msg.tokens.output = 4;
                    msg.tokens.cache_read = 0;
                    msg.tokens.cache_write = 0;
                    msg.tokens.reasoning = 0;
                    msg.source_cost = 0.0;
                    msg
                })
                .collect::<Vec<_>>();

            assert_eq!(
                replace_rollup_source(&mut conn, "codex", &file, &replacement).unwrap(),
                1
            );
            assert_eq!(usage_session_count(&conn, "codex"), 0);
            assert_eq!(source_rollup_count(&conn, "codex"), 1);
            assert_eq!(agent_rollup_totals(&conn, "codex"), (15_000, 20_000, 5_000));
            let replacement_db_size = sqlite_db_size_bytes(&conn);
            assert!(
                replacement_db_size < 1_000_000,
                "usage.sqlite should stay bounded after source replacement, got {replacement_db_size} bytes"
            );
        });
    }

    #[test]
    fn monitoring_scan_caps_events_and_cache_prevents_repeat_growth() {
        with_home(|home| {
            let path = home.join(".qwen/telemetry.log");
            let expected_events = MAX_EVENTS_PER_FILE + 75;
            let retained_monitoring_records =
                crate::adapter::sqlite::queries::MAX_UNUPLOADABLE_PENDING_RECORD_ROWS as usize;
            let events = (0..expected_events)
                .map(|idx| {
                    serde_json::json!({
                        "time_unix_nano": 1_781_604_000_000_000_000_i64 + (idx as i64 * 1_000_000_000_i64),
                        "name": "qwen-code.user_prompt",
                        "attributes": {
                            "session.id": "bounded-qwen-session",
                            "prompt_id": format!("prompt-{idx}"),
                            "prompt": format!("bounded local prompt {idx}"),
                            "model": "qwen3-coder-plus"
                        }
                    })
                })
                .collect::<Vec<_>>();
            write_lines(&path, &events);

            let mut conn = open_usage_db().unwrap();
            let first = tokio_test::block_on(scan_into(
                &mut conn,
                UsageScanOptions {
                    tools: vec!["qwen".to_string()],
                    since: Some("2026-06-16".to_string()),
                    until: Some("2026-06-16".to_string()),
                },
                None,
            ))
            .unwrap();
            assert_eq!(first.files_scanned, 1);
            assert_eq!(first.monitoring_events_parsed, expected_events);
            assert_eq!(first.monitoring_records_inserted, expected_events);
            assert_eq!(monitoring_rows().len(), retained_monitoring_records);
            assert_eq!(monitoring_seen_count(&conn), expected_events as i64);

            let second = tokio_test::block_on(scan_into(
                &mut conn,
                UsageScanOptions {
                    tools: vec!["qwen".to_string()],
                    since: Some("2026-06-16".to_string()),
                    until: Some("2026-06-16".to_string()),
                },
                None,
            ))
            .unwrap();
            assert_eq!(second.files_scanned, 0);
            assert_eq!(second.monitoring_events_parsed, 0);
            assert_eq!(second.monitoring_records_inserted, 0);
            assert_eq!(monitoring_rows().len(), retained_monitoring_records);
            assert_eq!(monitoring_seen_count(&conn), expected_events as i64);

            let records_db_size_after_second = {
                let records = open_records_db().unwrap();
                sqlite_db_size_bytes(&records)
            };
            let body = events
                .iter()
                .map(Value::to_string)
                .collect::<Vec<_>>()
                .join("\n");
            fs::write(&path, format!("{body}\n# same events, touched source\n")).unwrap();

            let third = tokio_test::block_on(scan_into(
                &mut conn,
                UsageScanOptions {
                    tools: vec!["qwen".to_string()],
                    since: Some("2026-06-16".to_string()),
                    until: Some("2026-06-16".to_string()),
                },
                None,
            ))
            .unwrap();
            assert_eq!(third.files_scanned, 1);
            assert_eq!(third.monitoring_events_parsed, expected_events);
            assert_eq!(third.monitoring_records_inserted, 0);
            assert_eq!(monitoring_rows().len(), retained_monitoring_records);
            assert_eq!(monitoring_seen_count(&conn), expected_events as i64);
            let records = open_records_db().unwrap();
            let records_db_size_after_third = sqlite_db_size_bytes(&records);
            assert_eq!(
                records_db_size_after_third, records_db_size_after_second,
                "records.sqlite should not grow when a changed source replays already-seen monitoring events"
            );

            let usage_db_size = sqlite_db_size_bytes(&conn);
            assert!(
                usage_db_size < 1_000_000,
                "usage.sqlite should stay bounded with scan cache, got {usage_db_size} bytes"
            );
            let records = open_records_db().unwrap();
            let records_db_size = sqlite_db_size_bytes(&records);
            assert!(
                records_db_size < 2_000_000,
                "records.sqlite should stay bounded for capped local events, got {records_db_size} bytes"
            );
        });
    }

