    #[test]
    fn cursor_agent_transcript_reader_maps_native_usage_and_events() {
        with_home(|home| {
            let path = home.join(".cursor/projects/project-one/agent-transcripts/session.jsonl");
            write_lines(
                &path,
                &[
                    serde_json::json!({
                        "type": "session",
                        "session_id": "cursor-agent-session",
                        "timestamp": "2026-06-16T14:00:00Z",
                        "model": "gpt-5",
                        "provider": "cursor",
                        "workspace": home.to_string_lossy().to_string()
                    }),
                    serde_json::json!({
                        "type": "user",
                        "session_id": "cursor-agent-session",
                        "timestamp": "2026-06-16T14:00:00Z",
                        "content": "cursor transcript prompt"
                    }),
                    serde_json::json!({
                        "type": "assistant",
                        "session_id": "cursor-agent-session",
                        "timestamp": "2026-06-16T14:00:01Z",
                        "content": "cursor transcript output",
                        "usage": {
                            "input_tokens": 90,
                            "output_tokens": 36,
                            "cache_read_tokens": 7,
                            "cache_write_tokens": 2,
                            "reasoning_tokens": 5,
                            "cost": 0.013
                        },
                        "account": "local"
                    }),
                    serde_json::json!({
                        "type": "tool_call",
                        "session_id": "cursor-agent-session",
                        "timestamp": "2026-06-16T14:00:01Z",
                        "tool_name": "read_file",
                        "tool_call_id": "cursor-read",
                        "tool_arguments": {"path": "src/lib.rs"}
                    }),
                    serde_json::json!({
                        "type": "tool_call",
                        "session_id": "cursor-agent-session",
                        "timestamp": "2026-06-16T14:00:01Z",
                        "tool_name": "apply_patch",
                        "tool_call_id": "cursor-edit",
                        "tool_arguments": {"path": "src/cursor-agent.rs", "old": "old\n", "new": "new\n"}
                    }),
                    serde_json::json!({
                        "type": "tool_result",
                        "session_id": "cursor-agent-session",
                        "timestamp": "2026-06-16T14:00:01Z",
                        "tool_call_id": "cursor-read",
                        "tool_result": "cursor transcript file content"
                    }),
                ],
            );

            assert!(is_native_file("cursor", &path));
            let result = scan_source_file("cursor", &native_source_file(&path)).unwrap();
            assert!(result.messages.iter().any(|message| {
                message.session_id == "cursor-agent-session"
                    && message.usage_basis == UsageBasis::Native
                    && message.tokens.input == 90
                    && message.tokens.output == 36
                    && message.tokens.cache_read == 7
                    && message.tokens.reasoning == 5
                    && message.source_cost > 0.0
            }));
            let event_types = result
                .events
                .iter()
                .map(|event| event.event_type.as_str())
                .collect::<HashSet<_>>();
            for expected in ["prompt", "output", "tool", "tool_result", "edit"] {
                assert!(
                    event_types.contains(expected),
                    "missing {expected}, got {event_types:?}"
                );
            }
            assert!(result
                .events
                .iter()
                .any(|event| { event.prompt_text.as_deref() == Some("cursor transcript prompt") }));
            assert!(result.events.iter().any(|event| {
                event.event_type == "edit" && event.file_path == "src/cursor-agent.rs"
            }));
            assert!(result.events.iter().any(|event| {
                event.event_type == "tool_result"
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("cursor transcript file content"))
            }));
        });
    }

    #[test]
    fn cursor_state_vscdb_reader_maps_typed_composer_usage_and_events() {
        with_home(|home| {
            let path = home.join(
                "Library/Application Support/Cursor/User/workspaceStorage/workspace-one/state.vscdb",
            );
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            let conn = Connection::open(&path).unwrap();
            conn.execute_batch("CREATE TABLE ItemTable (key TEXT, value TEXT);")
                .unwrap();
            conn.execute(
                "INSERT INTO ItemTable(key, value) VALUES (?1, ?2)",
                params![
                    "cursorDiskKV.composerData",
                    serde_json::json!({
                        "session_id": "cursor-state-session",
                        "timestamp": "2026-06-16T14:00:00Z",
                        "model": "gpt-5",
                        "provider": "cursor",
                        "usage": {
                            "input_tokens": 90,
                            "output_tokens": 33,
                            "cache_read_tokens": 8,
                            "cache_write_tokens": 3,
                            "reasoning_tokens": 6,
                            "cost": 0.016
                        },
                        "account": "local",
                        "messages": [
                            {"type": "user", "content": "cursor state prompt"},
                            {"type": "assistant", "content": "cursor state output"},
                            {"type": "tool_call", "tool_name": "read_file", "tool_call_id": "cursor-state-read", "tool_arguments": {"path": "src/lib.rs"}},
                            {"type": "tool_call", "tool_name": "apply_patch", "tool_call_id": "cursor-state-edit", "tool_arguments": {"path": "src/cursor-state.rs", "old": "old\n", "new": "new\n"}},
                            {"type": "tool_result", "tool_call_id": "cursor-state-read", "tool_result": "cursor state file content"}
                        ]
                    })
                    .to_string()
                ],
            )
            .unwrap();

            assert!(is_native_file("cursor", &path));
            let cursor_state = agent::local_source_specs()
                .iter()
                .find(|spec| spec.agent == "cursor" && spec.label == "state-vscdb")
                .expect("cursor state-vscdb source spec missing");
            assert!(cursor_state.capabilities.token_usage);
            assert!(agent::source_has_full_upload_coverage(cursor_state));

            let result = scan_source_file("cursor", &native_source_file(&path)).unwrap();
            let usage = result
                .messages
                .iter()
                .find(|message| message.usage_basis == UsageBasis::Native)
                .expect("cursor state native usage row missing");
            assert_eq!(usage.session_id, "cursor-state-session");
            assert_eq!(usage.tokens.input, 90);
            assert_eq!(usage.tokens.output, 33);
            assert_eq!(usage.tokens.cache_read, 8);
            assert_eq!(usage.tokens.reasoning, 6);
            assert!(usage.source_cost > 0.0);

            let event_types = result
                .events
                .iter()
                .map(|event| event.event_type.as_str())
                .collect::<HashSet<_>>();
            for expected in ["prompt", "output", "tool", "tool_result", "edit"] {
                assert!(
                    event_types.contains(expected),
                    "missing {expected}, got {event_types:?}"
                );
            }
            assert!(result.events.iter().any(|event| {
                event.prompt_text.as_deref() == Some("cursor state prompt")
                    && event.session_id == "cursor-state-session"
            }));
            assert!(result.events.iter().any(|event| {
                event.event_type == "edit"
                    && event.file_path == "src/cursor-state.rs"
                    && event.session_id == "cursor-state-session"
            }));
            assert!(result.events.iter().any(|event| {
                event.event_type == "tool_result"
                    && event
                        .metadata
                        .as_deref()
                        .is_some_and(|metadata| metadata.contains("cursor state file content"))
            }));
        });
    }

