    #[test]
    fn copilot_scan_window_prioritizes_registered_native_sources() {
        with_home(|home| {
            write_matrix_fixture(home, "copilot");

            let mut conn = open_usage_db().unwrap();
            let report = tokio_test::block_on(scan_into(
                &mut conn,
                UsageScanOptions {
                    tools: vec!["copilot".to_string()],
                    since: None,
                    until: None,
                },
                Some("device-copilot-priority"),
            ))
            .unwrap();

            assert_eq!(report.files_scanned, MAX_SCAN_FILES_PER_RUN);
            assert!(report.scan_budget_exhausted);
            assert!(report.parsed_messages >= 3, "report={report:?}");
            assert!(
                report.monitoring_events_parsed
                    >= realistic_fixture_min_monitoring_events("copilot"),
                "report={report:?}"
            );

            let scanned = scan_file_cache_paths(&conn, "copilot");
            for expected in [
                "/.copilot/otel/session-copilot.jsonl",
                "/.copilot/session-state/copilot-official-session/events.jsonl",
                "/.copilot/session-state/copilot-session/events.jsonl",
                "/.copilot/session-store.db",
                "/workspaceStorage/copilot-workspace/state.vscdb",
            ] {
                assert!(
                    scanned.iter().any(|path| path.contains(expected)),
                    "copilot scan should include {expected}, scanned={scanned:?}"
                );
            }

            let rollup_paths = rollup_source_paths(&conn, "copilot");
            assert!(
                rollup_paths
                    .iter()
                    .any(|path| path.contains("/.copilot/otel/session-copilot.jsonl")),
                "copilot OTEL usage source missing, rollup_paths={rollup_paths:?}"
            );
        });
    }

