    #[tokio::test(flavor = "current_thread")]
    async fn outbox_upload_success_deletes_synced_payload_rows() {
        let mock_server = MockServer::start().await;
        Mock::given(method("POST"))
            .and(path("/api/v1/ai-track/usage/rollup"))
            .and(header("X-AiTrack-Device", "device-outbox-delete"))
            .respond_with(ResponseTemplate::new(200).set_body_json(serde_json::json!({"ok": true})))
            .mount(&mock_server)
            .await;

        let _guard = ENV_LOCK.lock().unwrap_or_else(|p| p.into_inner());
        let dir = TempDir::new().unwrap();
        std::env::set_var("AITRACK_HOME", dir.path());
        std::env::set_var("AITRACK_SCAN_HOME", dir.path());
        crate::config::save_config(&crate::config::Config {
            api_url: mock_server.uri(),
            credential: "aitrack_testtoken12345-testhmacsecret".to_string(),
            device_id: "device-outbox-delete".to_string(),
        })
        .unwrap();
        let mut conn = open_usage_db().unwrap();
        let file = test_source_file(dir.path(), "sources/codex/outbox-delete.jsonl");
        replace_rollup_source(&mut conn, "codex", &file, &[make_message(11)]).unwrap();
        assert_eq!(
            enqueue_dirty_rollups(&conn, "device-outbox-delete").unwrap(),
            1
        );
        let payload_bytes_before: i64 = conn
            .query_row(
                "SELECT COALESCE(SUM(length(payload_json)), 0) FROM usage_outbox",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert!(payload_bytes_before > 0);

        let report = drain_outbox(
            &conn,
            &mock_server.uri(),
            "aitrack_testtoken12345-testhmacsecret",
            "device-outbox-delete",
        )
        .await
        .unwrap();
        assert_eq!(report.uploaded, 1);
        assert_eq!(report.failed, 0);
        let (outbox_rows, payload_bytes_after): (i64, i64) = conn
            .query_row(
                "SELECT COUNT(*), COALESCE(SUM(length(payload_json)), 0) FROM usage_outbox",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(outbox_rows, 0);
        assert_eq!(payload_bytes_after, 0);
        std::env::remove_var("AITRACK_HOME");
        std::env::remove_var("AITRACK_SCAN_HOME");
    }

    #[test]
    fn outbox_cleanup_prunes_failed_expired_and_payload_overflow() {
        with_home(|_| {
            let conn = open_usage_db().unwrap();
            conn.execute(
                "INSERT INTO usage_outbox
                 (payload_type, natural_key, payload_json, payload_sha256, retry_count)
                 VALUES ('rollup', 'fresh', '{}', 'fresh-sha', 0)",
                [],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO usage_outbox
                 (payload_type, natural_key, payload_json, payload_sha256, retry_count)
                 VALUES ('subscription', 'failed', '{}', 'failed-sha', ?1)",
                params![MAX_OUTBOX_RETRY_COUNT],
            )
            .unwrap();
            conn.execute(
                "INSERT INTO usage_outbox
                 (payload_type, natural_key, payload_json, payload_sha256, created_at)
                 VALUES ('rollup', 'expired', '{}', 'expired-sha', datetime('now', '-8 days'))",
                [],
            )
            .unwrap();

            assert_eq!(cleanup_usage_outbox(&conn).unwrap(), 2);
            let remaining_keys = conn
                .prepare("SELECT natural_key FROM usage_outbox ORDER BY id")
                .unwrap()
                .query_map([], |row| row.get::<_, String>(0))
                .unwrap()
                .collect::<rusqlite::Result<Vec<_>>>()
                .unwrap();
            assert_eq!(remaining_keys, vec!["fresh".to_string()]);

            for idx in 0..3 {
                let payload = format!("\"payload-{idx}\"");
                conn.execute(
                    "INSERT INTO usage_outbox
                     (payload_type, natural_key, payload_json, payload_sha256)
                     VALUES ('rollup', ?1, ?2, ?3)",
                    params![
                        format!("payload-{idx}"),
                        payload,
                        format!("payload-sha-{idx}")
                    ],
                )
                .unwrap();
            }

            assert_eq!(prune_usage_outbox_rows(&conn, 2).unwrap(), 2);
            let row_count: i64 = conn
                .query_row("SELECT COUNT(*) FROM usage_outbox", [], |row| row.get(0))
                .unwrap();
            assert_eq!(row_count, 2);

            assert_eq!(prune_usage_outbox_payload_bytes(&conn, 12).unwrap(), 1);
            let payload_bytes: i64 = conn
                .query_row(
                    "SELECT COALESCE(SUM(length(payload_json)), 0) FROM usage_outbox",
                    [],
                    |row| row.get(0),
                )
                .unwrap();
            assert!(payload_bytes <= 12);
        });
    }

    #[test]
    fn old_rollup_payload_ack_does_not_clear_new_dirty() {
        with_home(|home| {
            let mut conn = open_usage_db().unwrap();
            let file = test_source_file(home, "sources/codex/rollup-old-ack.jsonl");
            let first = make_message(21);
            replace_rollup_source(&mut conn, "codex", &file, &[first]).unwrap();
            assert_eq!(enqueue_dirty_rollups(&conn, "device-old-ack").unwrap(), 1);
            let old_item = fetch_pending_outbox(&conn).unwrap().remove(0);

            let mut changed = make_message(21);
            changed.tokens.input = 99;
            changed.tokens.output = 1;
            changed.tokens.cache_read = 0;
            changed.tokens.cache_write = 0;
            changed.tokens.reasoning = 0;
            changed.source_cost = 0.02;
            replace_rollup_source(&mut conn, "codex", &file, &[changed]).unwrap();

            mark_payload_uploaded(&conn, &old_item).unwrap();
            let dirty: i64 = conn
                .query_row(
                    "SELECT dirty FROM usage_daily_model_rollups
                     WHERE device_id = ?1 AND day = '2026-06-16'
                       AND agent = 'codex' AND model = 'gpt-5-20260101' AND account = 'local'",
                    params![load_config().device_id],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(dirty, 1);
        });
    }

